public class TaskListTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        TaskList empty = new TaskList();
        check("countDone on an empty list", 0, empty.countDone());
        check("pending on an empty list", "[]", String.valueOf(empty.pending()));
        check("markDone on an empty list", false, empty.markDone("nothing"));

        TaskList list = new TaskList();
        list.add(new Task("mail", 1));
        list.add(new Task("ship", 5));
        list.add(new Task("call", 3));
        list.add(new Task("file", 3));

        check("pending sorted by priority descending", "[ship(5, pending), call(3, pending), file(3, pending), mail(1, pending)]",
                String.valueOf(list.pending()));
        check("markDone on a stored task", true, list.markDone("ship"));
        check("markDone on a missing task", false, list.markDone("golf"));
        check("countDone after one task is done", 1, list.countDone());
        check("pending skips the done task", "[call(3, pending), file(3, pending), mail(1, pending)]",
                String.valueOf(list.pending()));
        check("markDone on an already-done task", true, list.markDone("ship"));
        check("countDone does not double count", 1, list.countDone());

        try {
            java.util.List<Task> snapshot = list.pending();
            snapshot.clear();
            check("pending returns a fresh list each time", 3, list.pending().size());
        } catch (RuntimeException e) {
            System.out.println("FAIL  pending returns a fresh list each time -- threw " + e);
            failures++;
        }

        list.markDone("mail");
        list.markDone("call");
        check("countDone after three are done", 3, list.countDone());
        check("only one task still pending", "[file(3, pending)]", String.valueOf(list.pending()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

